    def step(self, action):
        """action: (kind, arg) or None. Returns (obs, terminal_reason or None)."""
        self.steps += 1
        if action is None:
            self.msg = "Could not read an action. Use CLICK(n), TYPE(n, \"text\"), BACK or DONE(\"answer\")."
            return self.observe(), self._cap()
