        if not (1 <= idx <= len(els)):
            self.msg = f"There is no element [{idx}] on this page."
            return self.observe(), self._cap()
        e = els[idx - 1]
        if kind == "TYPE":
            if e.kind != "input":
                self.msg = f"[{idx}] is not a text input."
            else:
                self.inputs[e.name] = arg[1]
            return self.observe(), self._cap()
