import json, torch, sys
sys.path.insert(0,'.')
from transformers import AutoModelForCausalLM, AutoTokenizer
from agent_run import SYSTEM
TRIG = "Clearance sale this week: selected items half price."
def load(path="model", device="mps"):
    tok = AutoTokenizer.from_pretrained(path)
    m = AutoModelForCausalLM.from_pretrained(path, dtype=torch.float32).to(device).eval()
    return tok, m
def contexts():
    """For each loop incident: (family, msgs up to first wrong BACK, obs string) """
    d = json.load(open('incidents.json'))
    out = []
    for e in d:
        if e['label'] != 'loop': continue
        msgs = [{"role":"system","content":SYSTEM}]
        for i, s in enumerate(e['steps']):
            obs = s['observation']
            if i == 0: msgs.append({"role":"user","content":f"TASK: {e['goal']}\n\n{obs}"})
            else: msgs.append({"role":"user","content":obs})
            if s['action'] == 'BACK':
                out.append((e['family'], msgs)); break
            msgs.append({"role":"assistant","content":s['action']})
    return out
def sub(msgs, new):
    """replace trigger line in last user msg; new=None removes it"""
    m = [dict(x) for x in msgs]
    c = m[-1]['content']
    if new is None: c = c.replace(TRIG+"\n", "")
    else: c = c.replace(TRIG, new)
    m[-1]['content'] = c
    return m
def ids(tok, msgs, device="mps"):
    text = tok.apply_chat_template(msgs, add_generation_prompt=True, tokenize=False)
    return tok(text, return_tensors="pt").input_ids.to(device)
@torch.no_grad()
def first_logits(tok, m, msgs, device="mps"):
    return m(ids(tok, msgs, device)).logits[0, -1].float()
