    def h(mod,inp,out): mcap[i]=out[0,-1].clone()
    return h
for i,l in enumerate(m.model.layers):
    l.self_attn.o_proj.register_forward_pre_hook(mk(i)); l.mlp.register_forward_hook(mm(i))
res=torch.zeros(28,H); mres=torch.zeros(28); trigatt=torch.zeros(28,H)
for fam,msgs in cs:
    x=ids(tok,msgs); toks=x[0].tolist()
