    for l in range(28): trigatt[l]+=out.attentions[l][0,:,-1,pos].sum(-1).cpu()/len(cs)
    m(ids(tok,sub(msgs,NEU))); cn=dict(cap); mn=dict(mcap)
    for l in range(28):
