    def _h(self,i,kind):
        def h(mod,inp,out):
            P=self.A if kind=='A' else self.M
            if i in P:
                Q=P[i]; out=out-(out@Q.T)@Q
            (self.capA if kind=='A' else self.capM)[i]=out[0,-1].clone()
            return out
        return h
def collect(tok,m,pr,layers,ctx_idx=TRAIN_CTX,promo=PROMO_TR,neutral=NEUTRAL_TR):
    cs=contexts(); DA={i:[] for i in layers}; DM={i:[] for i in layers}
